import{_ as a,o as t,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — FR 3.6.2 / DA-978","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/plan.md","filePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/plan.md"}'),r={name:"feature/content-task-workflow/3-6-2-assign-task-to-creator/plan.md"};function o(s,e,c,h,l,m){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-—-fr-3-6-2-da-978" tabindex="-1">Plan — FR 3.6.2 / DA-978 <a class="header-anchor" href="#plan-—-fr-3-6-2-da-978" aria-label="Permalink to &quot;Plan — FR 3.6.2 / DA-978&quot;">​</a></h1><p>&gt; <strong>Ưu tiên BA mới 2026-10-15:</strong> xem <a href="./../task-five-state-inline-edit/spec.html">Task năm trạng thái + inline autosave</a>. TODO thay BACKLOG/DETAIL_IDENTIFIED/ASSIGNED; giao việc cần mô tả + deadline hợp lệ, không chuyển trạng thái. IN_REVIEW lưu bước QC/Manager/Client riêng, reject về IN_PROGRESS, bước cuối thành công mới FINISHED. Manager khóa sửa/giao lại sau lần bắt đầu đầu tiên. Phần vòng đời/form cũ bên dưới được giữ làm lịch sử, không phải contract mới. Đợt này chỉ code FR 3.6.1/2; Approval và Comments không được coi là đã hoàn thành.</p><p>2026-10-14. <a href="./spec.html">Spec confirmed, Q13 mới nhất</a>. Dùng <a href="./../task-workflow-contract.html">contract chung</a>.</p><h2 id="pham-vi-api-va-model" tabindex="-1">Phạm vi, API và model <a class="header-anchor" href="#pham-vi-api-va-model" aria-label="Permalink to &quot;Phạm vi, API và model&quot;">​</a></h2><p>Business TaskWorkflowService/Access/Store dùng cùng DTO/model/lock với FR3.6.1. Q13 thay Q12: không có visibility hoặc ràng buộc nội bộ + Client duyệt. requiresClientApproval là checkbox độc lập cho mọi nguồn Task; true/false chỉ cấu hình chuỗi duyệt kết quả. Schema nền vẫn optional để tương thích writers cũ; không tự sửa legacy data. POST <code>.../tasks/{taskId}/assign</code> nhận User IDs, requiresClientApproval, expectedRevision. POST <code>.../tasks/{taskId}/start</code> chỉ assignee, expectedRevision; action do Creator bấm rõ ràng. Trả status ASSIGNED/IN_PROGRESS uppercase, revision mới và capabilities. Errors contract §3. Thêm assignedAt/By, firstStartedAt/By optional vào tasks; outbox notification riêng.</p><h2 id="luong" tabindex="-1">Luồng <a class="header-anchor" href="#luong" aria-label="Permalink to &quot;Luồng&quot;">​</a></h2><p>Giao lần đầu DETAIL_IDENTIFIED → ASSIGNED; giao lại trước start giữ ASSIGNED. Kiểm tra Creator/QC active cùng WS, khác nhau; không nhận membership ID thay User ID. CAS revision/status/start marker + Campaign lock; Mongo transaction Task + outbox. Creator mới nhận thông báo một lần/assignment event; retry không nhân đôi. Start chỉ ghi marker đầu tiên; reject không xóa marker, submit/resubmit do E51-03 phối hợp. Không sửa approvalRound/history, không giao/bắt đầu Task terminal hoặc Campaign completed.</p><h2 id="frontend-va-dependencies" tabindex="-1">Frontend và dependencies <a class="header-anchor" href="#frontend-va-dependencies" aria-label="Permalink to &quot;Frontend và dependencies&quot;">​</a></h2><p>Assign form trong Task Detail, member options scoped, nút start riêng cho assignee; không thêm hành vi tự start vào editor. <code>src/locales/{vi,en}/tasks.json</code> assignment/actions/errors song song, semantic light/dark, empty members/loading/conflict/keyboard states. E51-03 phải review marker/CAS/approval resets; E51-05 cùng list điểm vào. Risk: reject có ASSIGNED nhưng đã start; legacy marker thiếu; người bị gỡ membership; outbox SQL idempotency, tránh hứa distributed transaction. Trình tự: schema → membership/options → assign/start guards → outbox worker → UI → race tests.</p><h2 id="implementation-slice-2026-10-15" tabindex="-1">Implementation slice 2026-10-15 <a class="header-anchor" href="#implementation-slice-2026-10-15" aria-label="Permalink to &quot;Implementation slice 2026-10-15&quot;">​</a></h2><p>Thêm workflow DTO/actions, member options chỉ Creator active với User ID. Không ghi specialist metadata/approvalRound. Task + TASK_ASSIGNED outbox cùng Mongo transaction; worker lease token, retry và SQL INSERT ON CONFLICT (id), recheck active Creator/Task scope trước delivery. Chỉ sự kiện TASK_ASSIGNED trong đợt này; không claim comments/Approval đã triển khai. Schema missing không tự create; worker bỏ qua khi collection chưa có. UI form có expectedRevision, giữ draft khi 409 và nút reload riêng. Locale thực tế src/i18n/locales/{vi,en}/tasks.json.</p>',11)])])}const g=a(r,[["render",o]]);export{p as __pageData,g as default};
